//! Vector-driven unit tests. Every expected value comes from
//! `contract-tests/vectors/*.json`, which is generated by running the Python
//! reference implementation.

use std::fs;

use axum::http::{HeaderMap, HeaderValue};
use chrono::{DateTime, Utc};
use ipnet::IpNet;
use serde_json::Value;

use crate::auth::lms;
use crate::auth::password;
use crate::auth::rate_limit;
use crate::config::{self, RateLimitConfig};
use crate::json_fmt::TsOffset;
use crate::routes::auth::python_int_string;
use crate::routes::auth::school_id_from_email;
use crate::routes::threads::valid_image_magic;

fn vector(name: &str) -> Value {
    let path = format!(
        "{}/../contract-tests/vectors/{}",
        env!("CARGO_MANIFEST_DIR"),
        name
    );
    serde_json::from_str(
        &fs::read_to_string(&path).unwrap_or_else(|error| panic!("read {path}: {error}")),
    )
    .expect("valid vector JSON")
}

fn fixture(name: &str) -> String {
    let path = format!(
        "{}/../contract-tests/fixtures/{}",
        env!("CARGO_MANIFEST_DIR"),
        name
    );
    fs::read_to_string(&path).unwrap_or_else(|error| panic!("read {path}: {error}"))
}

#[test]
fn query_integer_vectors() {
    let data = vector("parsing.json");
    for case in data["query_int"].as_array().unwrap() {
        let input = case["input"].as_str().unwrap();
        match case.get("value").and_then(Value::as_str) {
            Some(expected) => {
                let expected = expected.parse::<i64>().unwrap_or(i64::MAX);
                assert_eq!(
                    crate::extract::parse_int_lax(input),
                    Some(expected),
                    "query int {input:?}"
                );
            }
            None => assert_eq!(
                case["error"].as_str(),
                Some("int_parsing"),
                "unexpected vector for {input:?}"
            ),
        }
    }
}

#[test]
fn form_and_query_boolean_vectors() {
    let data = vector("parsing.json");
    for case in data["form_and_query_bool"].as_array().unwrap() {
        let input = case["input"].as_str().unwrap();
        match case.get("value").and_then(Value::as_bool) {
            Some(expected) => assert_eq!(
                crate::extract::parse_bool(input),
                Some(expected),
                "bool {input:?}"
            ),
            None => assert_eq!(
                crate::extract::parse_bool(input),
                None,
                "bool {input:?} must be rejected"
            ),
        }
    }
}

#[test]
fn env_flag_and_positive_integer_vectors() {
    let data = vector("parsing.json");
    for case in data["env_bool_flags"].as_array().unwrap() {
        let expected = case["AUTH_COOKIE_SECURE"].as_bool().unwrap();
        match case["value"].as_str() {
            Some(value) => assert_eq!(config::flag_value(value), expected, "flag {value:?}"),
            None => assert!(expected, "unset AUTH_COOKIE_SECURE defaults to true"),
        }
    }
    for case in data["env_positive_ints"].as_array().unwrap() {
        let expected = case["parsed_with_default_10"].as_i64().unwrap();
        assert_eq!(
            config::parse_positive_int(case["value"].as_str(), 10),
            expected,
            "positive int {:?}",
            case["value"]
        );
    }
}

