#[test]
fn client_ip_vectors() {
    let data = vector("client_ip.json");
    for case in data["cases"].as_array().unwrap() {
        let cidrs: Vec<IpNet> = case["AUTH_RATE_LIMIT_TRUSTED_PROXY_CIDRS"]
            .as_str()
            .unwrap()
            .split(',')
            .map(str::trim)
            .filter(|item| !item.is_empty())
            .filter_map(|item| item.parse().ok())
            .collect();
        let config = RateLimitConfig {
            subject_limit: 10,
            global_limit: 300,
            window_seconds: 60,
            trust_proxy: config::trust_proxy_flag_value(
                case["AUTH_RATE_LIMIT_TRUST_PROXY_HEADERS"]
                    .as_str()
                    .unwrap(),
            ),
            trusted_proxies: cidrs,
        };
        let mut headers = HeaderMap::new();
        if let Some(value) = case["x_forwarded_for"].as_str() {
            headers.insert("x-forwarded-for", HeaderValue::from_str(value).unwrap());
        }
        let peer: std::net::IpAddr = case["peer"].as_str().unwrap().parse().unwrap_or_else(|_| {
            // "testclient" is not an IP; the reference treats it as the direct peer.
            "0.0.0.0".parse().unwrap()
        });
        let expected = case["expected"].as_str().unwrap();
        if case["peer"].as_str() == Some("testclient") {
            assert_eq!(rate_limit::client_ip(peer, &headers, &config), "0.0.0.0");
        } else {
            assert_eq!(
                rate_limit::client_ip(peer, &headers, &config),
                expected,
                "client ip case {:?}",
                case["name"]
            );
        }
    }
}

#[test]
fn bcrypt_vectors() {
    let data = vector("bcrypt.json");
    for case in data["cases"].as_array().unwrap() {
        let password = case["password"].as_str().unwrap();
        let hash = case["hash"].as_str().unwrap();
        assert_eq!(
            password::verify(password, hash),
            case["matches"].as_bool().unwrap(),
            "bcrypt password {password:?}"
        );
    }
    assert_eq!(
        password::hash("x").unwrap()[..7],
        data["generated_hash_prefix"].as_str().unwrap()[..7]
    );
    assert!(password::hash("x").unwrap().starts_with("$2b$12$"));
}

#[test]
fn upload_magic_vectors() {
    let data = vector("upload_magic.json");
    for case in data["image"].as_array().unwrap() {
        let bytes = hex::decode(case["hex"].as_str().unwrap()).unwrap();
        assert_eq!(
            valid_image_magic(&bytes),
            case["valid_image"].as_bool().unwrap(),
            "image case {:?}",
            case["name"]
        );
    }
    for case in data["pdf"].as_array().unwrap() {
        let bytes = hex::decode(case["hex"].as_str().unwrap()).unwrap();
        assert_eq!(
            bytes.starts_with(b"%PDF-"),
            case["valid_pdf"].as_bool().unwrap(),
            "pdf case {:?}",
            case["name"]
        );
    }
}

