#[test]
fn rate_limit_key_vectors() {
    let data = vector("rate_limit.json");
    for case in data["window_keys"].as_array().unwrap() {
        let (key, retry) = rate_limit::window_key_at(
            case["identifier"].as_str().unwrap(),
            case["now"].as_i64().unwrap(),
            case["window_seconds"].as_i64().unwrap(),
        );
        assert_eq!(key, case["key"].as_str().unwrap());
        assert_eq!(retry, case["window_ttl"].as_i64().unwrap());
    }
    for case in data["subjects"].as_array().unwrap() {
        let subject = case["subject"].as_str().unwrap();
        assert_eq!(
            caseless::default_case_fold_str(subject),
            case["casefolded"].as_str().unwrap(),
            "casefold {subject:?}"
        );
    }
}

#[test]
fn jwt_vectors_from_python_are_accepted() {
    let data = vector("jwt.json");
    let key = data["hash_key"].as_str().unwrap();
    for case in data["python_issued"].as_array().unwrap() {
        let expected = &case["claims"];
        let token_type = expected["type"].as_str().unwrap();
        let claims =
            crate::auth::jwt::decode_with_key(key, case["token"].as_str().unwrap(), token_type)
                .unwrap_or_else(|error| panic!("python token rejected: {error}"));
        assert_eq!(claims["sub"], expected["sub"]);
        assert_eq!(claims["id"], expected["id"]);
        assert_eq!(claims["adm"], expected["adm"]);
    }
    for case in data["adm_claim_format"].as_array().unwrap() {
        let ids: Vec<String> = case["ids"]
            .as_array()
            .unwrap()
            .iter()
            .map(|id| id.as_str().unwrap().to_string())
            .collect();
        assert_eq!(
            crate::auth::jwt::adm_claim(&ids),
            case["adm"].as_str().unwrap()
        );
    }
}

#[test]
fn email_rendering_vectors() {
    let data = vector("email.json");
    for case in data["rendered"].as_array().unwrap() {
        let cta = case.get("cta").filter(|value| !value.is_null()).map(|cta| {
            (
                cta["text"].as_str().unwrap().to_string(),
                cta["link"].as_str().unwrap().to_string(),
            )
        });
        let html = crate::mail::render(
            case["title"].as_str().unwrap(),
            case["content"].as_str().unwrap(),
            cta.as_ref()
                .map(|(text, link)| (text.as_str(), link.as_str())),
        );
        assert_eq!(
            html,
            case["html"].as_str().unwrap(),
            "email {:?}",
            case["event"]
        );
    }
    for case in data["send_email_calls"].as_array().unwrap() {
        let service_name = case["SERVICE_NAME"].as_str().unwrap_or("local");
        assert_eq!(
            crate::mail::subject(service_name, "審核通過"),
            case["subject"].as_str().unwrap()
        );
    }
}

#[test]
fn lms_fixture_vectors() {
    let data = vector("lms.json");
    let scenarios = data["scenarios"].as_array().unwrap();
    let success = &scenarios[0];
    assert_eq!(success["scenario"], "success");
    let login = fixture("lms/login_success.html");
    assert_eq!(lms::parse_login_html(&login).unwrap(), "20261105093015");
    let (readable_name, department) =
        lms::parse_course_info_html(&fixture("lms/course_info.html")).unwrap();
    assert_eq!(readable_name, success["user_info"]["readable_name"]);
    assert_eq!(department, success["user_info"]["department"]);
    assert_eq!(
        lms::parse_contact_html(&fixture("lms/contact.html")).unwrap(),
        success["user_info"]["email"].as_str().map(str::to_string)
    );
    assert_eq!(
        lms::parse_contact_html(&fixture("lms/contact_without_email.html")).unwrap(),
        None
    );

    let error = lms::parse_login_html(&fixture("lms/login_failure.html")).unwrap_err();
    assert_eq!(error.to_string(), "Incorrect username or password");

    let missing_email = scenarios
        .iter()
        .find(|scenario| scenario["scenario"] == "contact_page_without_email_value")
        .unwrap();
    assert!(missing_email["user_info"]["email"].is_null());
}

#[test]
fn timestamp_serialization_vectors() {
    let whole: DateTime<Utc> = "2026-01-02T03:04:05Z".parse().unwrap();
    assert_eq!(
        serde_json::to_string(&TsOffset(Some(whole))).unwrap(),
        "\"2026-01-02T03:04:05+00:00\""
    );
    let micros: DateTime<Utc> = "2026-01-02T03:04:05.123456Z".parse().unwrap();
    assert_eq!(
        serde_json::to_string(&TsOffset(Some(micros))).unwrap(),
        "\"2026-01-02T03:04:05.123456+00:00\""
    );
    assert_eq!(
        serde_json::to_string(&crate::json_fmt::TsZ(Some(whole))).unwrap(),
        "\"2026-01-02T03:04:05Z\""
    );
}
